internal/cli/pattern_refresh_regression_test.go
package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestRootCommandPatternsRefreshTextContract(t *testing.T) {
	opts, repoDir, brainDir := commandRegressionFixture(t)
	out, stderr, err := executeSplit(t, NewRootCommand(opts), "patterns", "refresh", repoDir)
	if err != nil {
		t.Fatalf("refresh: %v\nstdout=%s\nstderr=%s", err, out, stderr)
	}
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	if manifest.Sources == nil || manifest.Sources.Patterns == nil || manifest.Sources.Patterns.Episodes == 0 {
		t.Fatal("refresh did not publish a nonempty episode source")
	}
	source := manifest.Sources.Patterns
	r := source.Reinforcement
	want := fmt.Sprintf("patterns: rebuilt %d episode(s) (success %d, corrected %d, neutral %d)\n", source.Episodes, r.Success, r.Corrected, r.Neutral)
	if out != want || stderr != "" {
		t.Fatalf("refresh output: stdout=%q stderr=%q; want stdout=%q and empty stderr", out, stderr, want)
	}
	if info, err := os.Stat(filepath.Join(brainDir, filepath.FromSlash(patternCorpusPath))); err != nil || !info.Mode().IsRegular() {
		t.Fatalf("successful refresh did not publish corpus: %v", err)
	}
}

func TestRootCommandPatternsRefreshFailureDoesNotReportSuccess(t *testing.T) {
	for _, asJSON := range []bool{false, true} {
		t.Run(fmt.Sprintf("json=%t", asJSON), func(t *testing.T) {
			opts, repoDir, brainDir := commandRegressionFixture(t)
			// A directory at the database path is a portable, real publication
			// failure, unlike permission bits which differ across OSes and users.
			corpus := filepath.Join(brainDir, filepath.FromSlash(patternCorpusPath))
			if err := os.MkdirAll(corpus, 0o700); err != nil {
				t.Fatal(err)
			}
			canary := filepath.Join(corpus, "keep")
			if err := os.WriteFile(canary, []byte("existing data"), 0o600); err != nil {
				t.Fatal(err)
			}
			args := []string{"patterns", "refresh", repoDir}
			if asJSON {
				args = append(args, "--json")
			}
			out, _, err := executeSplit(t, NewRootCommand(opts), args...)
			if err == nil || !strings.Contains(err.Error(), "pattern corpus:") {
				t.Fatalf("refresh should fail at corpus build: err=%v stdout=%q", err, out)
			}
			if out != "" {
				t.Fatalf("failed refresh published success output: %q", out)
			}
			if data, err := os.ReadFile(canary); err != nil || string(data) != "existing data" {
				t.Fatalf("failed refresh changed existing data: %q, %v", data, err)
			}
		})
	}
}
internal/cli/pattern_ranking_regression_test.go
package cli

import "testing"

func TestRankTaskRelevantPatternsRanksRelevanceBeforeStrength(t *testing.T) {
	views := []patternView{
		{ID: "one", Title: "Deploy service", Strength: 0.99},
		{ID: "two", Title: "Deploy service rollback", Strength: 0.10},
		{ID: "kind", Title: "Release notes", Kind: "deploy procedure", Strength: 0.20},
		{ID: "noise", Title: "Database migration", Strength: 1.00},
	}

	got := rankTaskRelevantPatterns(views, []string{"deploy", "service", "rollback"}, 10)
	if ids := patternViewIDs(got); !sameStrings(ids, []string{"two", "one", "kind"}) {
		t.Fatalf("rankTaskRelevantPatterns IDs = %v, want [two one kind]", ids)
	}
}

func TestRankTaskRelevantPatternsCountsRepeatedWordsOnceAndKeepsStableTies(t *testing.T) {
	views := []patternView{
		{ID: "first", Title: "Deploy deploy", Strength: 0.50},
		{ID: "second", Title: "Deploy service", Strength: 0.50},
		{ID: "third", Title: "Deploy service", Strength: 0.50},
	}

	got := rankTaskRelevantPatterns(views, []string{"deploy", "service"}, 10)
	if ids := patternViewIDs(got); !sameStrings(ids, []string{"second", "third", "first"}) {
		t.Fatalf("rankTaskRelevantPatterns IDs = %v, want [second third first]", ids)
	}
}

func TestRankTaskRelevantPatternsDropsNonOverlappingPatternsAndHonorsLimit(t *testing.T) {
	views := []patternView{
		{ID: "first", Title: "Deploy service rollback", Strength: 0.10},
		{ID: "second", Title: "Deploy service", Strength: 0.90},
		{ID: "third", Title: "Deploy", Strength: 0.80},
		{ID: "noise", Title: "Database migration", Strength: 1.00},
	}

	got := rankTaskRelevantPatterns(views, []string{"deploy", "service", "rollback"}, 2)
	if ids := patternViewIDs(got); !sameStrings(ids, []string{"first", "second"}) {
		t.Fatalf("rankTaskRelevantPatterns IDs = %v, want [first second]", ids)
	}
}

func TestRankTaskRelevantPatternsReturnsNilForEmptyInputs(t *testing.T) {
	views := []patternView{{ID: "deploy", Title: "Deploy service", Strength: 0.50}}

	for name, tc := range map[string]struct {
		terms []string
		limit int
	}{
		"empty terms":    {terms: nil, limit: 5},
		"zero limit":     {terms: []string{"deploy"}, limit: 0},
		"negative limit": {terms: []string{"deploy"}, limit: -1},
	} {
		t.Run(name, func(t *testing.T) {
			if got := rankTaskRelevantPatterns(views, tc.terms, tc.limit); got != nil {
				t.Fatalf("rankTaskRelevantPatterns = %#v, want nil", got)
			}
		})
	}
}

func patternViewIDs(views []patternView) []string {
	ids := make([]string, len(views))
	for i, view := range views {
		ids[i] = view.ID
	}
	return ids
}

func sameStrings(got, want []string) bool {
	if len(got) != len(want) {
		return false
	}
	for i := range got {
		if got[i] != want[i] {
			return false
		}
	}
	return true
}
