	if limit <= 0 || len(terms) == 0 {
		return nil
	}
	termSet := make(map[string]bool, len(terms))
	for _, t := range terms {
		termSet[t] = true
	}
	type scored struct {
		v       patternView
		overlap int
	}
	var matched []scored
	for _, v := range views {
		seen := map[string]bool{}
		overlap := 0
		for _, w := range brainBriefTaskWordPattern.FindAllString(strings.ToLower(v.Title+" "+v.Kind), -1) {
			if termSet[w] && !seen[w] {
				seen[w] = true
				overlap++
			}
		}
		if overlap > 0 {
			matched = append(matched, scored{v, overlap})
		}
	}
	sort.SliceStable(matched, func(i, j int) bool {
		if matched[i].overlap != matched[j].overlap {
			return matched[i].overlap > matched[j].overlap
		}
		return matched[i].v.Strength > matched[j].v.Strength
	})
	out := make([]patternView, 0, limit)
	for _, m := range matched {
		if len(out) >= limit {
			break
		}
		out = append(out, m.v)
	}
	return out
}"},{"rank":6,"score":43.7206,"file_path":"internal/cli/pattern_list_test.go","start_line":50,"end_line":54,"focus_line":52,"snippet_start_line":51,"snippet_end_line":52,"symbol_start_line":50,"symbol_end_line":72,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/pattern_list_test.go:function:TestPatternsListSuppressesRejected","symbol_name":"TestPatternsListSuppressesRejected","qualified_name":"TestPatternsListSuppressesRejected","signature":"func TestPatternsListSuppressesRejected(t *testing.T)","signals":["path","body","symbol-name","symbol-usage"],"snippet":"	brainDir := promotableCorpusDir(t, time.Now())
